static bool internal_clause_set_cell(Cell* cell, CellValue value, bool is_explicit);

// the full implication state generated by the rule
static ImplicState full_implic_state;

// these return the implic state mask for where the cell
// at position pos in the 10-bit state is on or off
static ImplicState IMPLICSTATE_CELL_ON_MASKS[10];
static ImplicState IMPLICSTATE_CELL_OFF_MASKS[10];

// IMPLICSTATE_PAIR_SAME_MASKS[pos1][pos2] returns the implic state mask for
// where the cells at position pos1 and pos2 have the same value
// and IMPLICSTATE_PAIR_DIFFERENT_MASKS is the same thing but the cell values must be different
static ImplicState IMPLICSTATE_PAIR_SAME_MASKS[10][10];
static ImplicState IMPLICSTATE_PAIR_DIFFERENT_MASKS[10][10];


#if defined(__AVX2__) || true

#include <immintrin.h>

static inline void implicstate_copy(ImplicState to, ImplicState from) {
    memcpy(to, from, sizeof(ImplicState));
}

static inline int implicstate_get_bit(ImplicState state, int bit) {
    return (state[bit >> 6] >> (bit & 63)) & 1;
}

static inline void implicstate_set_bit(ImplicState state, int bit, int value) {
    if (value == 0) {
        state[bit >> 6] &= ~((uint64_t)1 << (bit & 63));
    } else {
        state[bit >> 6] |= ((uint64_t)1 << (bit & 63));
    }
}

static void print_implicstate(ImplicState state) {
    printf("Implication state:\n");
    int k = 0;
    for (int i = 0; i < 16; i++) {
        print_line_padding();
        for (int j = 0; j < 64; j++) {
            real_printf("%i", implicstate_get_bit(state, k));
            k++;
        }
        real_printf("\n");
    }
}

static inline __m256i implicstate_avx2_load(ImplicState state, int v) {
    return _mm256_loadu_si256((const __m256i *)(state + 4 * v));
}

static inline void implicstate_avx2_store(ImplicState state, int v, __m256i x) {
    _mm256_storeu_si256((__m256i *)(state + 4 * v), x);
}

static inline __m256i implicstate_avx2_cell_ones(int pos, int v) {
    static const uint64_t LANE_PATTERNS[6] = {
        0xAAAAAAAAAAAAAAAAULL,
        0xCCCCCCCCCCCCCCCCULL,
        0xF0F0F0F0F0F0F0F0ULL,
        0xFF00FF00FF00FF00ULL,
        0xFFFF0000FFFF0000ULL,
        0xFFFFFFFF00000000ULL,
    };
    if (pos < 6) {
        return _mm256_set1_epi64x((long long)LANE_PATTERNS[pos]);
    }
    if (pos == 6) {
        return _mm256_set_epi64x(-1, 0, -1, 0);
    }
    if (pos == 7) {
        return _mm256_set_epi64x(-1, -1, 0, 0);
    }
    if (pos < 10) {
        return _mm256_set1_epi64x(((v >> (pos - 8)) & 1) ? -1 : 0);
    }
    return _mm256_setzero_si256();
}

static inline bool implicstate_eq(ImplicState x, ImplicState y) {
    __m256i diff = _mm256_setzero_si256();
    for (int i = 0; i < 4; i++) {
        diff = _mm256_or_si256(diff, _mm256_xor_si256(implicstate_avx2_load(x, i), implicstate_avx2_load(y, i)));
    }
    return _mm256_testz_si256(diff, diff);
}

static inline bool implicstate_is_contradiction(ImplicState state) {
    __m256i any = _mm256_setzero_si256();
    for (int i = 0; i < 4; i++) {
        any = _mm256_or_si256(any, implicstate_avx2_load(state, i));
    }
    return _mm256_testz_si256(any, any);
}

static inline bool implicstate_satisfies_mask(ImplicState state, ImplicState mask) {
    __m256i any = _mm256_setzero_si256();
    for (int i = 0; i < 4; i++) {
        any = _mm256_or_si256(any, _mm256_and_si256(implicstate_avx2_load(state, i), implicstate_avx2_load(mask, i)));
    }
    return !_mm256_testz_si256(any, any);
}

static inline void implicstate_set_cell(ImplicState state, int pos, int value) {
    for (int i = 0; i < 4; i++) {
        __m256i ones = implicstate_avx2_cell_ones(pos, i);
        __m256i s = implicstate_avx2_load(state, i);
        s = value ? _mm256_and_si256(ones, s) : _mm256_andnot_si256(ones, s);
        implicstate_avx2_store(state, i, s);
    }
}

static inline void implicstate_alias_cell(ImplicState state, int pos1, int pos2, bool invert) {
    for (int i = 0; i < 4; i++) {
        __m256i differ = _mm256_xor_si256(implicstate_avx2_cell_ones(pos1, i), implicstate_avx2_cell_ones(pos2, i));
        __m256i s = implicstate_avx2_load(state, i);
        s = invert ? _mm256_andnot_si256(differ, s) : _mm256_and_si256(differ, s);
        implicstate_avx2_store(state, i, s);
    }
}


#else

typedef uint64_t ImplicState[16];

static inline void implicstate_copy(ImplicState to, ImplicState from) {
    memcpy(to, from, sizeof(ImplicState));
}

static inline int implicstate_get_bit(ImplicState state, int bit) {
    return (state[bit >> 6] >> (bit & 63)) & 1;
}

static inline void implicstate_set_bit(ImplicState state, int bit, int value) {
    if (value == 0) {
        state[bit >> 6] &= ~((uint64_t)1 << (bit & 63));
    } else {
        state[bit >> 6] |= ((uint64_t)1 << (bit & 63));
    }
}

static void print_implicstate(ImplicState state) {
    printf("Implication state:\n");
    int k = 0;
    for (int i = 0; i < 16; i++) {
        print_line_padding();
        for (int j = 0; j < 64; j++) {
            real_printf("%i", implicstate_get_bit(state, k));
            k++;
        }
        real_printf("\n");
    }
}

static inline bool implicstate_eq(ImplicState x, ImplicState y) {
    for (int i = 0; i < 16; i++) {
        if (x[i] != y[i]) {
            return false;
        }
    }
    return true;
}

static inline bool implicstate_is_contradiction(ImplicState state) {
    for (int i = 0; i < 16; i++) {
        if (state[i] != 0) {
            return false;
        }
    }
    return true;
}

static inline bool implicstate_satisfies_mask(ImplicState state, ImplicState mask) {
    ImplicState value;
    memcpy(value, state, sizeof(ImplicState));
    for (int i = 0; i < 16; i++) {
        value[i] &= mask[i];
    }
    for (int i = 0; i < 16; i++) {
        if (value[i] != 0) {
            return true;
        }
    }
    return false;
}

static inline void implicstate_set_cell(ImplicState state, int pos, int value) {
    int k = 0;
    for (int i = 0; i < 16; i++) {
        for (int j = 0; j < 64; j++) {
            if (((k >> pos) & 1) != value) {
                state[i] &= ~((uint64_t)1 << j);
            }
            k++;
        }
    }
}

static inline void implicstate_alias_cell(ImplicState state, int pos1, int pos2, bool invert) {
    int k = 0;
    for (int i = 0; i < 16; i++) {
        for (int j = 0; j < 64; j++) {
            if ((((k >> pos1) & 1) != ((k >> pos2) & 1)) == invert) {
                state[i] &= ~((uint64_t)1 << j);
            }
            k++;
        }
    }
}


#endif


static void init_implicstate(void) {
    for (int i = 0; i < 512; i++) {
        if (state.trs[i]) {
            implicstate_set_bit(full_implic_state, i << 1, 0);
            implicstate_set_bit(full_implic_state, (i << 1) | 1, 1);
        } else {
            implicstate_set_bit(full_implic_state, i << 1, 1);
            implicstate_set_bit(full_implic_state, (i << 1) | 1, 0);
        }
    }
    #if DEBUG >= 2
        print_implicstate(full_implic_state);
    #endif
    for (int pos = 0; pos < 10; pos++) {
        for (int i = 0; i < 1024; i++) {
            if ((i >> pos) & 1) {
                implicstate_set_bit(IMPLICSTATE_CELL_ON_MASKS[pos], i, 1);
            } else {
                implicstate_set_bit(IMPLICSTATE_CELL_OFF_MASKS[pos], i, 1);
            }
        }
    }
    for (int pos1 = 0; pos1 < 10; pos1++) {
        for (int pos2 = 0; pos2 < 10; pos2++) {
            for (int i = 0; i < 1024; i++) {
                if ((i >> pos1) == (i >> pos2)) {
                    implicstate_set_bit(IMPLICSTATE_PAIR_SAME_MASKS[pos1][pos2], i, 1);
                } else {
                    implicstate_set_bit(IMPLICSTATE_PAIR_DIFFERENT_MASKS[pos1][pos2], i, 1);
                }
            }
        }
    }
}

static inline bool check_single_cell_implications(CAClause* clause, int pos, Cell* cell) {
    if (cell->value != UNKNOWN) {
        return true;
    }
    if (implicstate_is_contradiction(clause_state(clause))) {
        return false;
    }
    bool can_be_0 = implicstate_satisfies_mask(clause_state(clause), IMPLICSTATE_CELL_OFF_MASKS[pos]);
    bool can_be_1 = implicstate_satisfies_mask(clause_state(clause), IMPLICSTATE_CELL_ON_MASKS[pos]);
    debug_printf_4("Implication for clause %zu: pos = %i, variable = %zu, can_be_0 = %i, can_be_1 = %i\n", clause->number, pos, cell->var_number, can_be_0, can_be_1);
    #if DEBUG >= 5
    print_implicstate(clause_state(clause));
    #endif
    if (!can_be_0 && !can_be_1) {
        // it can't be anything, so contradiction!
        return false;
    } else if (!can_be_0 && can_be_1) {
        return internal_clause_set_cell(cell, ON, false);
    } else if (can_be_0 && !can_be_1) {
        return internal_clause_set_cell(cell, OFF, false);
    } else {
        // can't do anything with it
        return true;
    }
}

static bool check_implications(CAClause* clause) {
    return check_single_cell_implications(clause, 9, clause->nw)
        && check_single_cell_implications(clause, 8, clause->w)
        && check_single_cell_implications(clause, 7, clause->sw)
        && check_single_cell_implications(clause, 6, clause->n)
        && check_single_cell_implications(clause, 5, clause->c)
        && check_single_cell_implications(clause, 4, clause->s)
        && check_single_cell_implications(clause, 3, clause->ne)
        && check_single_cell_implications(clause, 2, clause->e)
        && check_single_cell_implications(clause, 1, clause->se)
        && check_single_cell_implications(clause, 0, clause->next)
    ;
}

static bool set_cell(Cell* cell, CellValue value) {
    // TODO: HANDLE ALIASES HERE
    cell->value = value;
    #if HAS_DEBUG_DEPTH
        debug_depth++;
        #define before_return debug_depth--;
    #else
        #define before_return
    #endif
    CAClause* changed_clauses[cell->use_count * 10];
    size_t changed_clause_count = 0;
    for (size_t i = 0; i < cell->use_count; i++) {
        CellUseData* data = &(cell->uses[i]);
        #if DEBUG >= 5
            #define hi print_implicstate
        #else
            #define hi(...)
        #endif
        #define update(clause, pos) \
            if ((clause) != NULL) { \
                debug_printf_4("Setting cell in clause %zu: pos = %i (aka "#clause"), value = %i, state_number = %i\n", (clause)->number, pos, value, (clause)->state_number); \
                hi(clause_state(clause)); \
                clause->state_number++; \
                implicstate_copy(clause_state(clause), clause->states[clause->state_number - 1]); \
                implicstate_set_cell(clause_state(clause), (pos), convert_12_to_01(value)); \
                hi(clause_state(clause)); \
                if (implicstate_is_contradiction(clause_state(clause))) { \
                    debug_printf_3("Contradiction in set_cell, unwinding\n"); \
                    cell->value = UNKNOWN; \
                    clause->state_number--; \
                    for (size_t i = 0; i < changed_clause_count; i++) { \
                        changed_clauses[i]->state_number--; \
                    } \
                    before_return; \
                    return false; \
                } \
                changed_clauses[changed_clause_count] = clause; \
                changed_clause_count++; \
            }
        update(data->prev, 0);
        update(data->nw, 1);
        update(data->w, 2);
        update(data->sw, 3);
        update(data->n, 4);
        update(data->c, 5);
        update(data->s, 6);
        update(data->ne, 7);
        update(data->e, 8);
        update(data->se, 9);
        #undef update
        #undef hi
    }
    before_return;
    return true;
}

static void unset_cell(Cell* cell) {
    // TODO: HANDLE ALIASES HERE
    cell->value = UNKNOWN;
    #if HAS_DEBUG_DEPTH
        debug_depth++;
    #endif
    for (size_t i = 0; i < cell->use_count; i++) {
        CellUseData* data = &(cell->uses[i]);
        #if DEBUG >= 5
            #define hi print_implicstate
        #else
            #define hi(...)
        #endif
        #define update(clause, pos) \
            if ((clause) != NULL) { \
                debug_printf_4("Unsetting cell in clause %zu: pos = %i (aka "#clause"), state_number = %i\n", (clause)->number, pos, (clause)->state_number); \
                hi(clause_state(clause)); \
                clause->state_number--; \
                hi(clause_state(clause)); \
            }
        update(data->prev, 0);
        update(data->nw, 1);
        update(data->w, 2);
        update(data->sw, 3);
        update(data->n, 4);
        update(data->c, 5);
        update(data->s, 6);
        update(data->ne, 7);
        update(data->e, 8);
        update(data->se, 9);
        #undef update
        #undef hi
    }
    #if HAS_DEBUG_DEPTH
        debug_depth--;
    #endif
}

static bool alias(Cell* cell, Cell* alias_to, bool invert) {
    // Cell* original_cell = cell;
    if (alias_to->alias) {
        invert = invert != alias_to->invert_alias;
        alias_to = alias_to->alias;
    }
    cell->alias = alias_to;
    cell->invert_alias = invert;
    // we have to do even more stuff now...
    // that is not yet implemented
    if (cell->value != alias_to->value) {
        unexpected_error("No aliasing yet");
    }
    return true;
}

static void unalias(Cell* cell) {
    cell->alias = NULL;
    // we have to do even more stuff here
    unexpected_error("No unaliasing yet");
}

static void compute_implication_state(CAClause* clause) {
    implicstate_copy(clause_state(clause), full_implic_state);
    #define add(cell, pos) \
        if ((cell)->value != UNKNOWN) { \
            implicstate_set_cell(clause_state(clause), (pos), convert_12_to_01((cell)->value)); \
        }
    add(clause->nw, 9);
    add(clause->w, 8);
    add(clause->sw, 7);
    add(clause->n, 6);
    add(clause->c, 5);
    add(clause->s, 4);
    add(clause->ne, 3);
    add(clause->e, 2);
    add(clause->se, 1);
    add(clause->next, 0);
    #undef add
    #if DEBUG >= 5
        printf("Initial state for clause %zu\n", clause->number);
        print_implicstate(clause_state(clause));
    #endif
}


// stack of clauses to check in set_cell_and_propagate
CAClause** clause_stack;
// stack pointer for `clause_stack`
CAClause** clause_sp;
// stack pointer for the done entries of clause_stack
CAClause** clause_done_sp;

static void init_clause_stack(void) {
    clause_stack = safe_malloc(16384 * sizeof(CAClause*));
}

static void destroy_clause_stack(void) {
    safe_free(clause_stack);
}

static bool internal_clause_set_cell(Cell* cell, CellValue value, bool is_explicit) {
    // maybe make its own function and manually inline and optimize the set_cell_and_push?
    // could be faster? depends on how clever the compiler is
    if (!set_cell_and_push(cell, value, is_explicit)) {
        return false;
    }
    for (size_t i = 0; i < cell->use_count; i++) {
        CellUseData* data = &(cell->uses[i]);
        #define add(clause) \
            if ((clause) != NULL) { \
                *clause_sp = (clause); \
                clause_sp++; \
            }
        add(data->c);
        add(data->prev);
        add(data->nw);
        add(data->w);
        add(data->sw);
        add(data->n);
        add(data->s);
        add(data->ne);
        add(data->e);
        add(data->se);
        #undef add
    }
    return true;
}

// set a cell in the search state, propagating checks
// returns false if contradiction, true if no contradiction
static bool set_cell_and_propagate(Cell* cell, CellValue value, bool is_explicit) {
    debug_printf_3("Setting cell and propagating: var_number = %zu\n", cell->var_number);
    clause_sp = &(clause_stack[0]);
    clause_done_sp = &(clause_stack[0]);
    if (!internal_clause_set_cell(cell, value, is_explicit)) {
        return false;
    }
    while (clause_done_sp < clause_sp) {
        debug_printf_3("Propagating: clause_sp = %ti, clause_done_sp = %ti\n", clause_sp - &(clause_stack[0]), clause_done_sp - &(clause_stack[0]));
        debug_print_grid_4();
        if (!check_implications(*clause_done_sp)) {
            return false;
        }
        clause_done_sp++;
    }
    return true;
}
